using System.Drawing;using System.Drawing.Drawing2D;using System.Reflection;using System.Runtime.CompilerServices;using System.Windows.Forms;
namespace AngraQaIntegration;
/// <summary>Read-only photographed guidance using the approved PET Coach vector glow.</summary>
public static class EmployeeTutorial {
 static bool observing;static readonly ConditionalWeakTable<Form,Button> buttons=new();
 public static readonly string[] Steps={"Proprietário: abra FUNCIONÁRIOS / PROPRIETÁRIO. Configure 001 somente se ainda não estiver ativo. Use sua senha apenas na página segura.","Na administração, informe a matrícula fixa (002 em diante), nome completo e perfil. Funcionário não cria a própria matrícula.","Marque as permissões desejadas para funcionário ou gerente. Só o proprietário pode conceder ou retirar opções.","Após cadastrar, guarde o código individual de ativação em segurança. É de uso único e vale 24 horas. Não o envie ao chat.","No celular do funcionário, conecte ao PDV e abra ATIVAR MATRÍCULA RECEBIDA. Informe matrícula e código e crie a própria senha.","Perdeu o código? Na administração, localize a pessoa e use REEMITIR ATIVAÇÃO. O código anterior deixa de funcionar; senha e sessões anteriores são revogadas.","Para revisar opções use ALTERAR PERFIL / PERMISSÕES. Para suspender use BLOQUEAR; para retirar o acesso use EXCLUIR ACESSO. Os dados comerciais permanecem."};
 public static void Observe(){if(observing)return;observing=true;Application.Idle+=Scan;Scan(null,EventArgs.Empty);}
 static IEnumerable<Control> All(Control root){yield return root;foreach(Control c in root.Controls)foreach(var x in All(c))yield return x;}
 static void Scan(object? s,EventArgs e){foreach(Form form in Application.OpenForms.Cast<Form>().ToArray())if(form.GetType().FullName=="LealInfoPDV.GlassWorkshopForm"&&form.GetType().Assembly.GetCustomAttributes<AssemblyMetadataAttribute>().Any(x=>x.Key=="PetIdentity"&&x.Value=="005"))Attach(form);}
 public static void Attach(Form form){if(buttons.TryGetValue(form,out _))return;var target=All(form).FirstOrDefault(c=>c.Name=="AngraOwnerAdministration"||c.Name=="AngraIntegration");if(target==null)return;var button=new Button{Name="AngraEmployeeTutorial",Text="COMO CADASTRAR FUNCIONÁRIOS",AutoSize=true,MinimumSize=new Size(240,44),AccessibleName="Como cadastrar funcionários"};
 if(target.Parent is FlowLayoutPanel flow){flow.Controls.Add(button);flow.Controls.SetChildIndex(button,Math.Min(flow.Controls.GetChildIndex(target)+1,flow.Controls.Count-1));}else{button.Dock=DockStyle.Bottom;form.Controls.Add(button);button.BringToFront();}buttons.Add(form,button);button.Click+=(_,_)=>new Guide(form,target).Show(form);}
 public sealed class Guide:VisualEmployeeGuide { public Guide(Form owner,Control target):base(owner,target){} }
}
